std::vector<std::vector<Point2d>> faces;

for (Arrangement::Face_circulator fc = arr.faces_begin(); fc != arr.faces_end(); ++fc) {
    if (arr.is_unbounded(*fc)) {
        continue;
    }

    std::vector<Point2d> face_points;

    // The outer boundary of a face is represented by its outer halfedge
    Arrangement::Halfedge_circulator hc = arr.outer_halfedge(*fc);
    if (hc == nullptr) {
        continue;
    }

    do {
        internal::Point_2 p = hc->source().point();
        double x, y;
        internal::getCoordinates(p, x, y);
        face_points.push_back(Point2d(x, y));
        hc = hc->next();
    } while (hc != arr.outer_halfedge(*fc));

    if (!face_points.empty()) {
        faces.push_back(face_points);
    }
}

return faces;

